83	// runCLIDiff 在真实进程上运行 diff，返回 stdout、stderr 与退出码。
84	func runCLIDiff(t *testing.T, bin, store, before, after string) (string, string, int) {
85		t.Helper()
86		cmd := exec.Command(bin, "diff", "--store", store, "--before", before, "--after", after)
87		var stdout, stderr bytes.Buffer
88		cmd.Stdout = &stdout
89		cmd.Stderr = &stderr
90		err := cmd.Run()
91		if err == nil {
92			return stdout.String(), stderr.String(), 0
93		}
94		if exitErr, ok := err.(*exec.ExitError); ok {
95			return stdout.String(), stderr.String(), exitErr.ExitCode()
96		}
97		t.Fatalf("failed to start diff: %v", err)
98		return "", "", 0
99	}
