	first, _, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
	if code != 0 {
		t.Fatal("first diff must succeed")
	}
	second, _, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
