	bad := auditDiffReport(t, bin, work, store, "bad.json", artifact, rules, diffAfterChecks(hash))
	if err := os.WriteFile(filepath.Join(store, bad.ReportID+".json"), []byte(`{broken`), 0o644); err != nil {
